import React from 'react';
import { graphql, Link } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import styled from 'styled-components';
import Layout from '../components/layout/Layout';

const BlogHero = styled.section`
  min-height: 40vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: ${props => props.theme.space[20]} ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-surface) 100%
  );
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(
      circle at 70% 50%,
      rgba(247, 147, 30, 0.15) 0%,
      transparent 60%
    );
    pointer-events: none;
  }
`;

const HeroContent = styled.div`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  position: relative;
  z-index: 1;
  text-align: center;
`;

const Title = styled.h1`
  font-size: ${props => props.theme.typography.fontSizes['6xl']};
  margin-bottom: ${props => props.theme.space[4]};
  background: linear-gradient(
    135deg,
    ${props => props.theme.colors.accent} 0%,
    ${props => props.theme.colors.primary} 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
  }
`;

const Subtitle = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.xl};
  color: var(--color-text-secondary);
  max-width: 700px;
  margin: 0 auto;
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
`;

const BlogSection = styled.section`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  padding: ${props => props.theme.space[16]} ${props => props.theme.space[6]};
`;

const PostList = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${props => props.theme.space[10]};
`;

const PostCard = styled(Link)`
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: ${props => props.theme.radii.xl};
  padding: ${props => props.theme.space[10]};
  transition: all 0.3s ease;
  text-decoration: none;
  display: block;

  &:hover {
    transform: translateX(8px);
    box-shadow: ${props => props.theme.shadows['2xl']};
    border-color: ${props => props.theme.colors.accent};
  }
`;

const PostMeta = styled.div`
  display: flex;
  align-items: center;
  gap: ${props => props.theme.space[3]};
  margin-bottom: ${props => props.theme.space[4]};
  font-size: ${props => props.theme.typography.fontSizes.sm};
  color: var(--color-text-secondary);
`;

const PostDate = styled.time`
  color: ${props => props.theme.colors.accent};
  font-weight: ${props => props.theme.typography.fontWeights.semibold};
`;

const PostTags = styled.div`
  display: flex;
  gap: ${props => props.theme.space[2]};
  flex-wrap: wrap;
`;

const Tag = styled.span`
  padding: ${props => props.theme.space[1]} ${props => props.theme.space[2]};
  background: rgba(247, 147, 30, 0.1);
  border-radius: ${props => props.theme.radii.sm};
  font-size: ${props => props.theme.typography.fontSizes.xs};
  color: ${props => props.theme.colors.accent};
`;

const PostTitle = styled.h2`
  font-size: ${props => props.theme.typography.fontSizes['3xl']};
  color: var(--color-text);
  margin-bottom: ${props => props.theme.space[3]};
`;

const PostDescription = styled.p`
  color: var(--color-text-secondary);
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
  font-size: ${props => props.theme.typography.fontSizes.lg};
`;

const EmptyState = styled.div`
  text-align: center;
  padding: ${props => props.theme.space[20]};
  color: var(--color-text-secondary);

  h2 {
    font-size: ${props => props.theme.typography.fontSizes['3xl']};
    margin-bottom: ${props => props.theme.space[4]};
  }
`;

function BlogPage({ data }) {
  const { t } = useTranslation();
  const posts = data.allMarkdownRemark.nodes;

  return (
    <Layout
      title={t('blog.title', 'Blog')}
      description={t('blog.subtitle', 'Thoughts on Complex Systems & Urban Science')}
      path="/blog"
    >
      <BlogHero>
        <HeroContent>
          <Title>{t('blog.title', 'Blog')}</Title>
          <Subtitle>
            {t('blog.subtitle', 'Thoughts on Complex Systems & Urban Science')}
          </Subtitle>
        </HeroContent>
      </BlogHero>

      <BlogSection>
        {posts.length > 0 ? (
          <PostList>
            {posts.map((post) => {
              const lang = post.frontmatter.lang || post.fields?.language || 'en-us';
              const basePath = lang === 'en-us' ? '/blog' : `/${lang}/blog`;
              const slug = post.fields?.slug || post.frontmatter.page_id;
              const path = `${basePath}/${slug}`;

              return (
                <PostCard key={post.id} to={path}>
                  <PostMeta>
                    {post.frontmatter.date && (
                      <PostDate>{post.frontmatter.date}</PostDate>
                    )}
                    {post.frontmatter.tags && post.frontmatter.tags.length > 0 && (
                      <>
                        <span>•</span>
                        <PostTags>
                          {post.frontmatter.tags.slice(0, 3).map((tag, i) => (
                            <Tag key={i}>{tag}</Tag>
                          ))}
                        </PostTags>
                      </>
                    )}
                  </PostMeta>
                  <PostTitle>{post.frontmatter.title}</PostTitle>
                  {post.frontmatter.description && (
                    <PostDescription>
                      {post.frontmatter.description}
                    </PostDescription>
                  )}
                </PostCard>
              );
            })}
          </PostList>
        ) : (
          <EmptyState>
            <h2>{t('blog.empty', 'No blog posts found')}</h2>
            <p>{t('blog.emptyDescription', 'Check back soon for new articles.')}</p>
          </EmptyState>
        )}
      </BlogSection>
    </Layout>
  );
}

export default BlogPage;

export const query = graphql`
  query BlogPageQuery($language: String!) {
    allMarkdownRemark(
      filter: {
        frontmatter: { type: { eq: "posts" } }
      }
      sort: { frontmatter: { date: DESC } }
    ) {
      nodes {
        id
        fields {
          slug
          language
        }
        frontmatter {
          page_id
          title
          description
          date(formatString: "MMMM DD, YYYY")
          tags
          lang
        }
      }
    }
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
